import assert from 'node:assert/strict';import {SpreadsheetParser} from '../../../src/lib/parser/spreadsheetParser.js';import {AnyDocParser} from '../../../src/lib/parser/anydocParser.js';import {evaluateBulkClientIsolation,type ClientIsolationBinding,type ClientIsolationScope} from '../../cpaOrganization/bulkClientIsolationEngine.js';import {CLIENTS,load,sha256,SHARED_LABEL,SHARED_PERIOD,SHARED_VALUE} from './clientIsolationFixture.js';
const spreadsheet=new SpreadsheetParser(),anydoc=new AnyDocParser();
const scope=(which:'ALPHA'|'BETA'):ClientIsolationScope=>({...CLIENTS[which]});
async function source(which:'ALPHA'|'BETA') {const c=CLIENTS[which],prefix=which.toLowerCase(),csv=load(which,'general-ledger.csv'),csvSha=sha256(csv),csvDoc:any=await spreadsheet.parse({filename:'general-ledger.csv',originalName:'general-ledger.csv',mimeType:'text/csv',size:csv.length,buffer:csv},{detectedType:'csv'} as any);assert.equal(csvDoc.source.hash,csvSha);const ref=csvDoc.tables[0].rowEvidence[0][3];assert.equal(ref.coordinate.sourceType,'CSV');assert.equal(ref.coordinate.rowIndex,2);assert.equal(ref.coordinate.columnIndex,4);const pdf=load(which,'expense-support.pdf'),pdfSha=sha256(pdf),pdfDoc:any=await anydoc.parse({filename:'expense-support.pdf',originalName:'expense-support.pdf',mimeType:'application/pdf',size:pdf.length,buffer:pdf},{detectedType:'pdf'} as any);assert.match(String(pdfDoc.raw_text||''),new RegExp(c.clientName.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')));const pdfArtifact=`artifact-pdf-${pdfSha.slice(0,24)}`,pdfProv=`prov-${prefix}-pdf-${pdfSha.slice(0,12)}`,pdfCoord={coordinateId:`coord-${pdfProv}`,sourceArtifactId:pdfArtifact,sourceSha256:pdfSha,sourceType:'PDF',pageNumber:1,rawLiteral:`${c.clientName} | ${SHARED_PERIOD} | ${SHARED_LABEL} | USD ${SHARED_VALUE.toFixed(2)}`,normalizedLiteral:`${c.clientName} | ${SHARED_PERIOD} | ${SHARED_LABEL} | USD ${SHARED_VALUE.toFixed(2)}`,nativeTextAvailable:true,evidenceMode:'NATIVE_TEXT',extractionMethod:'pdf-parse-native-text',extractionVersion:'1'};return {c,prefix,csvSha,csvRef:ref,pdfSha,pdfArtifact,pdfProv,pdfCoord};}
export async function prepareClientIsolation(){const a=await source('ALPHA'),b=await source('BETA'),scopes=[scope('ALPHA'),scope('BETA')];const bindings:ClientIsolationBinding[]=[];for(const s of [a,b]){const c=s.c,p=s.prefix,csvDoc=`doc-${p}-ledger`,pdfDoc=`doc-${p}-support`,csvProv=String(s.csvRef.provenanceId),csvArtifact=String(s.csvRef.coordinate.sourceArtifactId),csvFact=`fact-${p}-ledger-84-20`,pdfFact=`fact-${p}-support-84-20`;bindings.push(
 {kind:'DOCUMENT',id:csvDoc,...c,sourceSha256:s.csvSha,originalName:'general-ledger.csv'},
 {kind:'DOCUMENT',id:pdfDoc,...c,sourceSha256:s.pdfSha,originalName:'expense-support.pdf'},
 {kind:'PROVENANCE',id:csvProv,...c,sourceDocumentId:csvDoc,sourceSha256:s.csvSha,sourceArtifactId:csvArtifact,sourceCoordinate:s.csvRef.coordinate},
 {kind:'PROVENANCE',id:s.pdfProv,...c,sourceDocumentId:pdfDoc,sourceSha256:s.pdfSha,sourceArtifactId:s.pdfArtifact,sourceCoordinate:s.pdfCoord},
 {kind:'FACT',id:csvFact,...c,sourceDocumentId:csvDoc,provenanceId:csvProv,sourceSha256:s.csvSha,sourceArtifactId:csvArtifact,sourceCoordinate:s.csvRef.coordinate,label:SHARED_LABEL,period:SHARED_PERIOD,value:SHARED_VALUE,sourceText:`${c.clientName} ledger ${SHARED_LABEL} USD ${SHARED_VALUE.toFixed(2)}`},
 {kind:'FACT',id:pdfFact,...c,sourceDocumentId:pdfDoc,provenanceId:s.pdfProv,sourceSha256:s.pdfSha,sourceArtifactId:s.pdfArtifact,sourceCoordinate:s.pdfCoord,label:SHARED_LABEL,period:SHARED_PERIOD,value:SHARED_VALUE,sourceText:`${c.clientName} support ${SHARED_LABEL} USD ${SHARED_VALUE.toFixed(2)}`},
 {kind:'FINDING',id:`finding-${p}-office-supplies`,...c,sourceDocumentId:csvDoc,factId:csvFact,state:'OPEN'},
 {kind:'CLARIFICATION',id:`pbc-${p}-office-supplies`,...c,sourceDocumentId:pdfDoc,factId:pdfFact,state:'SUBMITTED_TO_CLIENT'},
 {kind:'RENDERED_VALUE',id:`render-${p}-office-supplies`,...c,factId:csvFact,value:SHARED_VALUE,state:'VISIBLE'}
 );}
 const cleanReview=evaluateBulkClientIsolation({scopes,bindings,reviewId:'bulk-client-clean'});const tampered=JSON.parse(JSON.stringify(bindings)) as ClientIsolationBinding[];const betaRender=tampered.find(x=>x.id==='render-beta-office-supplies')!;betaRender.factId='fact-alpha-ledger-84-20';const betaPbc=tampered.find(x=>x.id==='pbc-beta-office-supplies')!;betaPbc.sourceDocumentId='doc-alpha-support';const betaFact=tampered.find(x=>x.id==='fact-beta-support-84-20')!;betaFact.provenanceId=a.pdfProv;const tamperedReview=evaluateBulkClientIsolation({scopes,bindings:tampered,reviewId:'bulk-client-tampered'});const alphaBindings=bindings.filter(x=>x.clientId===CLIENTS.ALPHA.clientId),betaBindings=bindings.filter(x=>x.clientId===CLIENTS.BETA.clientId);const alphaReview=evaluateBulkClientIsolation({scopes:[scope('ALPHA')],bindings:alphaBindings,reviewId:'alpha-isolation'}),betaReview=evaluateBulkClientIsolation({scopes:[scope('BETA')],bindings:betaBindings,reviewId:'beta-isolation'});return {scopes,bindings,cleanReview,tamperedReview,alphaReview,betaReview,sourceShas:{ALPHA:[a.csvSha,a.pdfSha],BETA:[b.csvSha,b.pdfSha]},provenance:{ALPHA:[String(a.csvRef.provenanceId),a.pdfProv],BETA:[String(b.csvRef.provenanceId),b.pdfProv]}};}
function factFromBinding(b:any){return {id:b.id,workspaceId:b.workspaceId,documentId:b.sourceDocumentId,canonicalMetric:'operating_expenses',labelOriginal:b.label,labelNormalized:b.label,valueOriginal:String(b.value),valueFunctional:b.value,normalizedValue:b.value,currencyOriginal:'USD',functionalCurrency:'USD',reportingPeriod:b.period,status:'APPROVED',verificationStatus:'VERIFIED',evidenceStatus:'CONFIRMED',sourceDocument:b.sourceDocumentId?.includes('ledger')?'general-ledger.csv':'expense-support.pdf',documentTitle:b.sourceDocumentId?.includes('ledger')?'general-ledger.csv':'expense-support.pdf',sourceText:b.sourceText,sourceSha256:b.sourceSha256,sourceArtifactId:b.sourceArtifactId,sourceProvenanceId:b.provenanceId,sourceProvenanceIds:[b.provenanceId],sourceCoordinate:b.sourceCoordinate,sourceCoordinates:[b.sourceCoordinate],provenanceCoordinates:[b.sourceCoordinate]};}
export async function buildClientEngagement(which:'ALPHA'|'BETA'){const p=await prepareClientIsolation(),c=CLIENTS[which],review=which==='ALPHA'?p.alphaReview:p.betaReview,own=p.bindings.filter(x=>x.clientId===c.clientId),facts=own.filter(x=>x.kind==='FACT').map(factFromBinding),documents=own.filter(x=>x.kind==='DOCUMENT').map(x=>({id:x.id,filename:x.originalName,originalName:x.originalName,sha256:x.sourceSha256,workspaceId:c.workspaceId})),findings=own.filter(x=>x.kind==='FINDING').map(x=>({id:x.id,topic:'Office Supplies review',description:`${c.clientName} scoped finding`,status:x.state,documentId:x.sourceDocumentId,factIds:[x.factId]}));return {engagementId:c.engagementId,workspaceId:c.workspaceId,classification:'CUSTOMER',isCustomer:true,clientName:c.clientName,entityName:c.clientName,title:'Bulk Client Isolation',period:SHARED_PERIOD,framework:'US_GAAP',functionalCurrency:'USD',currentStage:'EVIDENCE_REVIEW',openReviewNotesCount:1,facts,canonicalFacts:facts,documents,reports:[],findings,periods:[SHARED_PERIOD],continuation:null,clientIsolationReview:review};}
