export function deliverableFacts(bindings:ClientIsolationBinding[],clientId:string){return bindings.filter(x=>x.clientId===clientId&&x.kind==='FACT').map((b:any)=>({id:b.id,canonicalMetric:'operating_expenses',label:b.label,value:b.value,statement:'CLIENT_SCOPED_EVIDENCE',sourceDoc:b.sourceDocumentId.includes('ledger')?'general-ledger.csv':'expense-support.pdf',documentId:b.sourceDocumentId,reportingPeriod:b.period,verificationStatus:'VERIFIED',evidenceStatus:'CONFIRMED',sourceText:b.sourceText,sourceSha256:b.sourceSha256,sourceArtifactId:b.sourceArtifactId,sourceProvenanceId:b.provenanceId,sourceProvenanceIds:[b.provenanceId],sourceCoordinate:b.sourceCoordinate,sourceCoordinates:[b.sourceCoordinate]}));}
